using System;

public class VisualColorTransition
{
    private Vec _current;
    private Vec _target;
    private Vec _start;
    private double _elapsed;
    private readonly double _duration = 1.5;
    private bool _initialized;

    public Vec Step(Vec target, double dt)
    {
        if (dt < 0) dt = 0;

        if (!_initialized)
        {
            _current = target;
            _target = target;
            _start = _current;
            _elapsed = 0;
            _initialized = true;
            return _current;
        }

        double diff = (target - _target).Length;
        if (diff > 1e-9)
        {
            _start = _current;
            _target = target;
            _elapsed = 0;
        }

        _elapsed += dt;
        double progress = _elapsed / _duration;
        if (progress > 1) progress = 1;
        if (progress < 0) progress = 0;

        _current = _start + (_target - _start) * progress;
        return _current;
    }
}
